DROP TABLE IF EXISTS `questions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `questions` (
  `id` varchar(191) NOT NULL,
  `vocabularyId` varchar(191) NOT NULL,
  `type` enum('ENGLISH_TO_CHINESE','CHINESE_TO_ENGLISH','LISTENING','FILL_IN_BLANK') NOT NULL,
  `content` varchar(191) NOT NULL,
  `sentence` varchar(191) DEFAULT NULL,
  `audioUrl` varchar(191) DEFAULT NULL,
  `correctAnswer` varchar(191) NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `questions_vocabularyId_fkey` (`vocabularyId`),
  CONSTRAINT `questions_vocabularyId_fkey` FOREIGN KEY (`vocabularyId`) REFERENCES `vocabularies` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
