DROP TABLE IF EXISTS `study_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `study_records` (
  `id` varchar(191) NOT NULL,
  `studentId` varchar(191) NOT NULL,
  `taskDate` date NOT NULL,
  `totalWords` int(11) NOT NULL,
  `completedWords` int(11) NOT NULL,
  `correctCount` int(11) NOT NULL,
  `wrongCount` int(11) NOT NULL,
  `accuracy` double NOT NULL,
  `totalTime` int(11) NOT NULL,
  `startedAt` datetime(3) NOT NULL,
  `completedAt` datetime(3) DEFAULT NULL,
  `isCompleted` tinyint(1) NOT NULL DEFAULT 0,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  `status` varchar(191) DEFAULT 'COMPLETED',
  `lastActiveAt` datetime(3) DEFAULT NULL,
  `isRetestMode` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `study_records_studentId_taskDate_idx` (`studentId`,`taskDate`),
  KEY `study_records_studentId_status_idx` (`studentId`,`status`),
  CONSTRAINT `study_records_studentId_fkey` FOREIGN KEY (`studentId`) REFERENCES `students` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

