DROP TABLE IF EXISTS `vocabularies`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `vocabularies` (
  `id` varchar(191) NOT NULL,
  `word` varchar(191) NOT NULL,
  `part_of_speech` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`part_of_speech`)),
  `primary_meaning` varchar(191) NOT NULL,
  `secondary_meaning` varchar(191) DEFAULT NULL,
  `phonetic` varchar(191) DEFAULT NULL,
  `phonetic_us` varchar(191) DEFAULT NULL,
  `phonetic_uk` varchar(191) DEFAULT NULL,
  `audio_url` varchar(191) DEFAULT NULL,
  `is_high_frequency` tinyint(1) NOT NULL DEFAULT 0,
  `difficulty` varchar(191) NOT NULL DEFAULT 'MEDIUM',
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `vocabularies_word_key` (`word`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

