  KEY `vocabulary_pack_day_words_vocabularyId_fkey` (`vocabularyId`),
  CONSTRAINT `vocabulary_pack_day_words_packDayId_fkey` FOREIGN KEY (`packDayId`) REFERENCES `vocabulary_pack_days` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `vocabulary_pack_day_words_vocabularyId_fkey` FOREIGN KEY (`vocabularyId`) REFERENCES `vocabularies` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
