DROP TABLE IF EXISTS `word_masteries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `word_masteries` (
  `id` varchar(191) NOT NULL,
  `studentId` varchar(191) NOT NULL,
  `vocabularyId` varchar(191) NOT NULL,
  `totalWrongCount` int(11) NOT NULL DEFAULT 0,
  `recentAccuracy` double DEFAULT NULL,
  `consecutiveCorrect` int(11) NOT NULL DEFAULT 0,
  `isMastered` tinyint(1) NOT NULL DEFAULT 0,
  `isDifficult` tinyint(1) NOT NULL DEFAULT 0,
  `lastPracticeAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `word_masteries_studentId_vocabularyId_key` (`studentId`,`vocabularyId`),
  KEY `word_masteries_studentId_isDifficult_idx` (`studentId`,`isDifficult`),
  KEY `word_masteries_studentId_isMastered_idx` (`studentId`,`isMastered`),
  KEY `word_masteries_vocabularyId_fkey` (`vocabularyId`),
  CONSTRAINT `word_masteries_studentId_fkey` FOREIGN KEY (`studentId`) REFERENCES `students` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `word_masteries_vocabularyId_fkey` FOREIGN KEY (`vocabularyId`) REFERENCES `vocabularies` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

