DROP TABLE IF EXISTS `word_meanings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `word_meanings` (
  `id` varchar(191) NOT NULL,
  `vocabularyId` varchar(191) NOT NULL,
  `partOfSpeech` varchar(191) NOT NULL,
  `meaning` varchar(191) NOT NULL,
  `orderIndex` int(11) NOT NULL DEFAULT 0,
  `examples` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`examples`)),
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `word_meanings_vocabularyId_idx` (`vocabularyId`),
  KEY `word_meanings_partOfSpeech_idx` (`partOfSpeech`),
  KEY `word_meanings_vocabularyId_orderIndex_idx` (`vocabularyId`,`orderIndex`),
  CONSTRAINT `word_meanings_vocabularyId_fkey` FOREIGN KEY (`vocabularyId`) REFERENCES `vocabularies` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

