--
-- Table structure for table `wrong_questions`
--

DROP TABLE IF EXISTS `wrong_questions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `wrong_questions` (
  `id` varchar(191) NOT NULL,
  `studentId` varchar(191) NOT NULL,
  `vocabularyId` varchar(191) NOT NULL,
  `questionId` varchar(191) NOT NULL,
  `wrongAnswer` varchar(191) NOT NULL,
  `correctAnswer` varchar(191) NOT NULL,
  `wrongCount` int(11) NOT NULL DEFAULT 1,
  `correctCount` int(11) NOT NULL DEFAULT 0,
  `status` enum('ACTIVE','CONFIRMED','MASTERED') NOT NULL DEFAULT 'ACTIVE',
  `wrongAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `lastReviewAt` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `wrong_questions_studentId_vocabularyId_idx` (`studentId`,`vocabularyId`),
  KEY `wrong_questions_studentId_status_idx` (`studentId`,`status`),
  KEY `wrong_questions_questionId_fkey` (`questionId`),
  KEY `wrong_questions_vocabularyId_fkey` (`vocabularyId`),
  CONSTRAINT `wrong_questions_questionId_fkey` FOREIGN KEY (`questionId`) REFERENCES `questions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `wrong_questions_studentId_fkey` FOREIGN KEY (`studentId`) REFERENCES `students` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `wrong_questions_vocabularyId_fkey` FOREIGN KEY (`vocabularyId`) REFERENCES `vocabularies` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

